            r,g,b=px[x,y]
            lum=(r+g+b)/3
            if lum < 80:
                dark.append((x,y,lum))
            elif lum > 200:
                bright.append((x,y,lum))
    print("dark", len(dark), "bright", len(bright))
    def cluster(pts, rad=12):
        clusters=[]
        for s in pts:
            placed=False
            for c in clusters:
                if abs(c[0]-s[0])<rad and abs(c[1]-s[1])<rad:
                    c[2].append(s)
                    n=len(c[2])
                    c[0]=sum(p[0] for p in c[2])/n
                    c[1]=sum(p[1] for p in c[2])/n
                    placed=True
                    break
            if not placed:
                clusters.append([s[0],s[1],[s]])
        return clusters
    if dark:
        cs=cluster(dark)
        cs.sort(key=lambda c: -len(c[2]))
        print(" dark clusters:")
